  "headline": "Ciprofloxacin hydrochloride is not on FDA's shortage list as of 2026-10-21; on-hand supply ranges from 13.2 to 29.5 days across sites",
  "headline_cites": ["D8", "D1", "D2", "D3", "D4", "D5", "D6", "D7"],
  "sentences": [
    {
      "text": "FDA's drug shortage list shows ciprofloxacin hydrochloride is not listed as of 2026-10-21.",
      "cites": ["D8"]
    },
    {
      "text": "Corvale East holds 299 tablets of the 250 mg strength at 16.2 tablets per day for 18.4 days on hand, and 426 tablets at 14.4 per day for 29.5 days on hand.",
      "cites": ["D1", "D3"]
    },
    {
      "text": "Corvale General holds 194 tablets of the 250 mg strength at 14.7 per day for 13.2 days on hand, and 251 tablets at 15.1 per day for 16.6 days on hand.",
      "cites": ["D2", "D4"]
    },
    {
      "text": "For the 500 mg strength, Corvale East holds 374 tablets at 16.2 per day for 23.2 days on hand, Corvale General holds 452 tablets at 15.6 per day for 29 days on hand, and Corvale Lakeside holds 73 tablets at 2.9 per day for 25.2 days on hand.",
      "cites": ["D5", "D6", "D7"]
    },
    {
      "text": "The top-ranked purchasing option is Amneal Pharmaceuticals NY LLC, which is not on FDA's shortage list today and its label names no plant we could place.",
      "cites": ["D9"]
    },
    {
      "text": "A label for Bryant Ranch Prepack (FEI 1000519407) shows a registered plant with a VAI inspection on 2026-07-16, but an earlier OAI inspection in 2009 and a Warning Letter in 2010-04-08 are recorded for the same FEI.",
      "cites": ["E19", "E9", "E18"]
    }
  ]
}
